    bodyC: "gSaveBlock1Ptr->pcItems[index].quantity -= count;\n    if (gSaveBlock1Ptr->pcItems[index].quantity == 0)\n    {\n        gSaveBlock1Ptr->pcItems[index].itemId = ITEM_NONE;\n        CompactPCItems();\n    }",
