  "RemovePyramidBagItem": {
    returnType: "bool8",
    params: "u16 itemId, u16 count",
    callsTo: ["Alloc","Free","memcpy"],
    lineCount: 53,
    bodyC: "u16 i;\n\n    u16 *items = gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode];\n    u8 *quantities = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode];\n\n    i = gPyramidBagMenuState.cursorPosition + gPyramidBagMenuState.scrollPosition;\n    if (items[i] == itemId && quantities[i] >= count)\n    {\n        quantities[i] -= count;\n        if (quantities[i] == 0)\n            items[i] = ITEM_NONE;\n        return TRUE;\n    }\n    else\n    {\n        u16 *newItems = Alloc(PYRAMID_BAG_ITEMS_COUNT * sizeof(*newItems));\n        u8 *newQuantities = Alloc(PYRAMID_BAG_ITEMS_COUNT * sizeof(*newQuantities));\n\n        memcpy(newItems, items, PYRAMID_BAG_ITEMS_COUNT * sizeof(*newItems));\n        memcpy(newQuantities, quantities, PYRAMID_BAG_ITEMS_COUNT * sizeof(*newQuantities));\n\n        for (i = 0; i < PYRAMID_BAG_ITEMS_COUNT; i++)\n        {\n            if (newItems[i] == itemId)\n            {\n                if (newQuantities[i] >= count)\n                {\n                    newQuantities[i] -= count;\n                    count = 0;\n                    if (newQuantities[i] == 0)\n                        newItems[i] = ITEM_NONE;\n                }\n                else\n                {\n                    count -= newQuantities[i];\n                    newQuantities[i] = 0;\n                    newItems[i] = ITEM_NONE;\n                }\n\n                if (count == 0)\n                    break;\n            }\n        }\n\n        if (count == 0)\n        {\n            memcpy(items, newItems, PYRAMID_BAG_ITEMS_COUNT * sizeof(*items));\n            memcpy(quantities, newQuantities, PYRAMID_BAG_ITEMS_COUNT * sizeof(*quantities));\n            Free(newItems);\n            Free(newQuantities);\n            return TRUE;\n        }\n        else\n        {\n            Free(newItems);\n            Free(newQuantities);\n            return FALSE;\n        }\n    }",
  },
